1281	  // `feet`, re-read fresh right above AFTER whatever depth was actually dug, so it always sits
1282	  // exactly 2 above the REAL resting feet (1 above the bot's own head) regardless of depth. The
1283	  // ring's own reference (one level below the ring, at the ring's horizontal offset) is the
1284	  // UNDISTURBED terrain surrounding the single dug column, at whatever absolute Y that lands —
1285	  // solid either way, since digDownInto only ever touches the center 1x1 column, never the
1286	  // footprint around it. A shallow (depth=1) dig-in's ring/cap ends up ABOVE original grade
1287	  // instead of at it, which looks odd on paper but is mechanically identical to depth=2's case
1288	  // one level up — same solid neighbours, same placement logic, no reference gap either way.
1289	  const sides = [[1, 0], [-1, 0], [0, 1], [0, -1]];
1290	  let r = await placeAt(cap);   // cheap check first — some geometry (a ledge, a rim) already has a reference
1291	  for (const s of sides) {
1292	    if (r === 'placed' || isSolid(bot.blockAt(cap))) break;
1293	    await placeAt(cap.offset(s[0], 0, s[1]));   // one ring cell — stops as soon as the cap itself succeeds
